(function(){"use strict";if(window.DuckNative){return;}
const bridge=window.AndroidDuckBridge;const pending=new Map();const listeners=new Map();let nextId=1;function makeError(code,message){const error=new Error(message);error.code=code;return error;}

function take(id){const entry=pending.get(id);if(!entry){return null;}
pending.delete(id);clearTimeout(entry.timer);return entry;}

function call(action,payload,options){return new Promise((resolve,reject)=>{if(!bridge||typeof bridge.request!=="function"){reject(makeError("NOT_SUPPORTED","Duck Bridge is not available"));return;}

const id=String(nextId++);let requestJson;try{requestJson=JSON.stringify({id,action,payload:payload??{}});}catch(error){reject(makeError("INVALID_PAYLOAD","Payload is not serializable"));return;}

const entry={resolve,reject,timer:null};const timeoutMs=options&&options.timeoutMs;if(timeoutMs>0){entry.timer=setTimeout(()=>{const expired=take(id);if(expired){expired.reject(makeError("TIMEOUT","Native call timed out"));}},timeoutMs);}
pending.set(id,entry);try{bridge.request(requestJson);}catch(error){const failed=take(id);if(failed){failed.reject(makeError("NATIVE_ERROR","Native bridge call failed"));}}});}

function resolve(id,response){const entry=take(String(id));if(!entry){return;}
if(response&&response.ok){entry.resolve(response.result??null);return;}
entry.reject(makeError(response?.error?.code??"NATIVE_ERROR",response?.error?.message??"Native operation failed"));}

function on(event,callback){let callbacks=listeners.get(event);if(!callbacks){callbacks=new Set();listeners.set(event,callbacks);}
callbacks.add(callback);return()=>off(event,callback);}

function off(event,callback){listeners.get(event)?.delete(callback);}

function dispatch(event,payload){for(const callback of Array.from(listeners.get(event)??[])){try{callback(payload??{});}catch(error){console.error("DuckNative listener failed",error);}}}
window.DuckNative=Object.freeze({call,resolve,on,off,dispatch});window.dispatchEvent(new Event("DuckNativeReady"));})();
